import time
import numpy as np
import mujoco


def make_model():
    return mujoco.MjModel.from_xml_path('model_ref.xml')


def run(model, seed, tmax=2.0):
    d = mujoco.MjData(model)
    rng = np.random.default_rng(seed)
    d.qpos += rng.normal(0, 0.01, size=d.qpos.shape)
    mujoco.mj_forward(model, d)
    n = int(tmax / model.opt.timestep)
    t0 = time.perf_counter()
    for _ in range(n):
        mujoco.mj_step(model, d)
    el = time.perf_counter() - t0
    st = np.zeros(mujoco.mj_stateSize(model, mujoco.mjtState.mjSTATE_FULLPHYSICS))
    mujoco.mj_getState(model, d, st, mujoco.mjtState.mjSTATE_FULLPHYSICS)
    return st, el

seeds = [0, 1, 2]
refs = {}
for s in seeds:
    m = make_model()
    refs[s], _ = run(m, s, tmax=2.0)

print('baseline states captured')

variants = []
variants.append(('baseline', {}))
variants.append(('no_contact', {'disableflags': 'contact'}))
variants.append(('no_actuator', {'disableflags': 'actuator'}))
variants.append(('no_contact_actuator_sensor', {'disableflags': 'contact|actuator|sensor'}))
variants.append(('no_contact_actuator_sensor_island', {'disableflags': 'contact|actuator|sensor|island'}))
variants.append(('geom_no_collide', {'geom_nocollide': True}))
for it in [50, 20, 10, 5, 3, 2, 1]:
    variants.append((f'iter{it}', {'iterations': it}))
for it in [20, 10, 5, 3, 2, 1]:
    variants.append((f'lsiter{it}', {'ls_iterations': it}))
for it in [5, 3, 2, 1]:
    variants.append((f'iter{it}_ls1', {'iterations': it, 'ls_iterations': 1}))
for dt in [0.0021, 0.0022, 0.0025, 0.004, 0.005]:
    variants.append((f'dt{dt}', {'timestep': dt}))

flags = {
    'contact': mujoco.mjtDisableBit.mjDSBL_CONTACT,
    'actuator': mujoco.mjtDisableBit.mjDSBL_ACTUATOR,
    'sensor': mujoco.mjtDisableBit.mjDSBL_SENSOR,
    'island': mujoco.mjtDisableBit.mjDSBL_ISLAND,
}

for name, cfg in variants:
    try:
        sts = {}
        els = []
        for s in seeds:
            m = make_model()
            if 'disableflags' in cfg:
                df = 0
                for f in cfg['disableflags'].split('|'):
                    df |= int(flags[f])
                m.opt.disableflags = df
            if 'geom_nocollide' in cfg:
                m.geom_contype[:] = 0
                m.geom_conaffinity[:] = 0
            if 'iterations' in cfg:
                m.opt.iterations = cfg['iterations']
            if 'ls_iterations' in cfg:
                m.opt.ls_iterations = cfg['ls_iterations']
            if 'timestep' in cfg:
                m.opt.timestep = cfg['timestep']
            st, el = run(m, s)
            sts[s] = st
            els.append(el)
            if not np.all(np.isfinite(st)):
                raise FloatingPointError('non-finite state')
        maxdiff = max(float(np.max(np.abs(sts[s] - refs[s]))) for s in seeds)
        ok = maxdiff <= 1e-5
        print(f'{name:38s} maxdiff={maxdiff:.3e} ok={ok} time={np.mean(els):.3f}s')
    except Exception as e:
        print(f'{name:38s} ERROR {type(e).__name__}: {e}')
